int handle_untagged_imap_responses(struct ImapData *idata) {
    if (!idata || !idata->conn) {
        return -1;
    }

    char *line = NULL;
    size_t line_len = 0;
    int ret;

    while ((ret = imap_read_line(idata->conn, &line, &line_len)) == 0) {
        if (!line || line_len == 0) {
            continue;
        }

        if (strncmp(line, "* EXISTS", 8) == 0) {
            int new_count = 0;
            if (sscanf(line, "* %d EXISTS", &new_count) == 1) {
                idata->new_mail_count = new_count;
            }
        } else if (strncmp(line, "* EXPUNGE", 9) == 0) {
            int seq_num = 0;
            if (sscanf(line, "* %d EXPUNGE", &seq_num) == 1) {
                handle_expunge(idata, seq_num);
            }
        } else if (strncmp(line, "* FETCH", 7) == 0) {
            handle_fetch_response(idata, line, line_len);
        } else if (strncmp(line, "* CAPABILITY", 12) == 0) {
            update_capabilities(idata, line + 12);
        } else if (strncmp(line, "* OK", 4) == 0 || strncmp(line, "* NO", 4) == 0 || strncmp(line, "* BAD", 5) == 0) {
            LOG_DEBUG("Untagged OK/NO/BAD: %s", line);
        } else {
            LOG_DEBUG("Received untagged IMAP response: %s", line);
        }

        free(line);
        line = NULL;
        line_len = 0;
    }

    if (ret < 0) {
        LOG_ERROR("Error reading IMAP response.");
        free(line);
        return -1;
    }

    if (ret == 1) {
        LOG_DEBUG("Connection closing.");
        return 0;
    }

    return 0;
}

int handle_untagged_response(struct ImapData *idata) {
    const char *resp = idata->response_buffer;
    int len = strlen(resp);

    if (strncmp(resp, "* EXISTS", len) == 0) {
        int count;
        sscanf(resp + 1, "%d", &count);
        idata->new_mail_count = count - idata->current_mail_count;
        idata->current_mail_count = count;
        return 0;
    } else if (strncmp(resp, "* EXPUNGE", len) == 0) {
        idata->mailbox_expunged = 1;
        return 0;
    } else if (strncmp(resp, "* FETCH", len) == 0) {
        // Handle message fetch
        return 0;
    } else if (strncmp(resp, "* CAPABILITY", len) == 0) {
        idata->server_capabilities = strdup(resp);
        return 0;
    } else if (strncmp(resp, "* OK", len) == 0) {
        idata->connection_status = IMAP_CONNECTED;
        return 0;
    } else if (strncmp(resp, "* BYE", len) == 0) {
        // Server is closing the connection
        return 0;
    } else if (strncmp(resp, "* NO", len) == 0) {
        // Non-fatal server error
        fprintf(stderr, "IMAP server error: %s\n", resp);
        return 0;
    } else if (strncmp(resp, "* BAD", len) == 0) {
        // Fatal error from server
        fprintf(stderr, "IMAP fatal error: %s\n", resp);
        return -1;
    }

    // Default case: unknown untagged response
    return 0;
}

